parameters.jsCode:
const items = $input.all();
const webhookData = $('Webhook').first().json;
const ocrData = $('Mistral OCR Extract').first().json;

const results = items.map(item => {
  // Check for API errors
  if (item.json.error) {
    return {
      json: {
        success: false,
        error: {
          code: item.json.error.code || 500,
          message: item.json.error.message || 'Translation API error',
          status: 'API_ERROR'
        },
        meta: {
          provider: 'mistral-ocr+openai'
        }
      }
    };
  }

  try {
    const originalContent = ocrData.choices?.[0]?.message?.content || '';
    const translatedContent = item.json.choices?.[0]?.message?.content || '';

    // Calculate statistics
    const originalWords = originalContent.split(/\s+/).filter(w => w.length > 0).length;
    const translatedWords = translatedContent.split(/\s+/).filter(w => w.length > 0).length;
    const mathFormulas = (originalContent.match(/\$[^$]+\$/g) || []).length;
    const tables = (originalContent.match(/\|[^|]+\|/g) || []).length > 0;

    return {
      json: {
        success: true,
        data: {
          original_content: originalContent,
          translated_content: translatedContent,
          source_language: webhookData.body.source_language || 'auto',
          target_language: webhookData.body.target_language || 'fr',
          statistics: {
            original_words: originalWords,
            translated_words: translatedWords,
            formulas_preserved: mathFormulas,
            has_tables: tables
          }
        },
        meta: {
          provider: 'mistral-ocr+openai',
          ocr_model: 'pixtral-12b-2409',
          translation_model: 'gpt-4o'
        }
      }
    };
  } catch (e) {
    return {
      json: {
        success: false,
        error: {
          code: 500,
          message: 'Failed to process translation: ' + e.message,
          status: 'PROCESS_ERROR'
        },
        meta: {
          provider: 'mistral-ocr+openai'
        }
      }
    };
  }
});

return results;
